// Motion packs: ready-made motion for Motion Transfer. Each pack is a texture moved in one
// characteristic way, generated by FFmpeg on the spot (nothing to download, no licences), then
// encoded like the timeline so its motion frames can be spliced straight into the mosh.
import { encoderArgs, even } from './args';
import type { EncoderSettings } from './types';

export interface MotionPack {
  id: string;
  name: string;
  hint: string;
}

export const MOTION_PACKS: MotionPack[] = [
  { id: 'drift', name: 'Drift', hint: 'Everything slides sideways.' },
  { id: 'fall', name: 'Fall', hint: 'Everything pours downwards, like rain.' },
  { id: 'vortex', name: 'Vortex', hint: 'The picture spins around the centre.' },
  { id: 'tunnel', name: 'Tunnel', hint: 'Zooming in, again and again: the picture explodes outwards.' },
  { id: 'implode', name: 'Implode', hint: 'Zooming out: the picture is sucked into the middle.' },
  { id: 'shake', name: 'Shake', hint: 'Handheld jitter in every direction.' },
  { id: 'ripple', name: 'Ripple', hint: 'Watery waves wobble through the picture.' },
  { id: 'life', name: 'Life', hint: 'Cellular automaton: blocks crawl and multiply like living things.' },
];

export const PACK_SECONDS = 8;

/**
 * A still, blobby texture of the given size: coarse noise scaled up, so it has features of
 * several sizes for motion search to latch onto.
 */
const texture = (w: number, h: number, fps: number, d: number) =>
  `color=c=0x7f7f7f:s=${even(w / 8)}x${even(h / 8)}:r=${fps}:d=${d},noise=c0s=100:c0f=u,scale=${even(w)}:${even(h)}:flags=bicubic,noise=c0s=25:c0f=u,eq=contrast=1.6`;

/** FFmpeg lavfi graph that renders a pack at w×h. */
export function packGraph(id: string, w: number, h: number, fps: number, d = PACK_SECONDS): string {
  const crop = `crop=${w}:${h}`;
  switch (id) {
    case 'drift':
      return `${texture(w, h, fps, d)},scroll=horizontal=0.006`;
    case 'fall':
      return `${texture(w, h, fps, d)},scroll=vertical=-0.015`;
    case 'vortex': {
      // a square big enough to cover the frame at any angle
      const side = Math.ceil(Math.hypot(w, h)) + 8;
      return `${texture(side, side, fps, d)},rotate=a=0.035*n:c=0x7f7f7f,${crop}`;
    }
    case 'tunnel':
      return `${texture(w, h, fps, d)},zoompan=z='1+mod(on\\,48)*0.015':d=1:x='iw/2-iw/zoom/2':y='ih/2-ih/zoom/2':s=${w}x${h}:fps=${fps}`;
    case 'implode':
      return `${texture(w, h, fps, d)},zoompan=z='1.72-mod(on\\,48)*0.015':d=1:x='iw/2-iw/zoom/2':y='ih/2-ih/zoom/2':s=${w}x${h}:fps=${fps}`;
    case 'shake':
      return `${texture(w * 1.2, h * 1.2, fps, d)},crop=${w}:${h}:x='(iw-ow)/2+${Math.round(w * 0.04)}*sin(n*1.7)':y='(ih-oh)/2+${Math.round(h * 0.04)}*cos(n*2.3)'`;
    case 'ripple':
      return `${texture(w, h, fps, d)},format=gray,geq=lum='lum(X+${Math.max(3, Math.round(w / 80))}*sin((Y+N*4)/11)\\,Y+${Math.max(3, Math.round(h / 60))}*cos((X+N*3)/13))',format=yuv420p`;
    case 'life':
      return `life=s=${even(w)}x${even(h)}:r=${fps}:ratio=0.14:mold=8:life_color=0xe0e0e0:death_color=0x202020:mold_color=0x805030,trim=duration=${d}`;
    default:
      throw new Error('unknown motion pack ' + id);
  }
}

/** Arguments that render a pack and encode it exactly like the timeline (one keyframe, then motion). */
export function packArgs(id: string, enc: EncoderSettings, w: number, h: number, out: string): string[] {
  return ['-f', 'lavfi', '-i', packGraph(id, w, h, enc.fps), '-t', String(PACK_SECONDS), '-an', '-pix_fmt', 'yuv420p', '-s', `${even(w)}x${even(h)}`, ...encoderArgs({ ...enc, gop: 100000, sceneCut: false }, []), '-f', 'avi', out];
}
